+export async function renderReportPdf(html: string): Promise<Uint8Array> {
+  const { BrowserWindow } = await import("electron");
+  const win = new BrowserWindow({ show: false, webPreferences: {
+    javascript: false, sandbox: true, nodeIntegration: false, contextIsolation: true,
+    backgroundThrottling: false,
+  } });
+  let timer: ReturnType<typeof setTimeout> | undefined;
+  try {
+    win.webContents.setWindowOpenHandler(() => ({ action: "deny" }));
+    return await Promise.race([
+      (async () => {
+        await win.loadURL(`data:text/html;charset=utf-8,${encodeURIComponent(html)}`);
+        return await win.webContents.printToPDF({ printBackground: true, pageSize: "A4", preferCSSPageSize: true });
+      })(),
+      new Promise<never>((_, reject) => { timer = setTimeout(() => reject(new Error("PDF generation timed out after 15 seconds.")), 15_000); }),
